def transform(grid):
    from collections import deque
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            edge = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                edge |= y == 0 or x == 0 or y == h - 1 or x == w - 1
                for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 8 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            if not edge:
                for y, x in comp:
                    out[y][x] = 4
    return out
